#!/usr/bin/env node
/*
 * Cross-browser QA of dist/FBAR-Max-Balance.html, opened from file:// in Chromium, WebKit (stands in for
 * Safari) and Firefox through Playwright. FAKE DATA ONLY (generated by qa/make_qa_files.py, which also runs
 * tests/make_fake_statements.py). Never point this at real bank statements.
 *
 *   cd qa && node run.mjs [--out DIR] [--browsers chromium,webkit,firefox] [--no-shots] [--keep-data]
 *
 * DIR (default qa/out, or $QA_OUT) receives the generated PDFs, the Python reference CSVs, downloads,
 * screenshots and results.json. Exit code 1 if any scenario FAILs.
 */
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { chromium, webkit, firefox } from 'playwright';

const QA = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(QA, '..');
const PY = path.join(ROOT, '.venv', 'bin', 'python');
const HTML = path.join(ROOT, 'dist', 'FBAR-Max-Balance.html');
const PAGE_URL = pathToFileURL(HTML).href;

const argv = process.argv.slice(2);
const opt = (name, dflt) => { const i = argv.indexOf('--' + name); return i >= 0 ? argv[i + 1] : dflt; };
const flag = (name) => argv.includes('--' + name);
const OUT = path.resolve(opt('out', process.env.QA_OUT || path.join(QA, 'out')));
const BROWSERS = opt('browsers', 'chromium,webkit,firefox').split(',').map((s) => s.trim()).filter(Boolean);
const SHOTS = !flag('no-shots');
const ENGINES = { chromium, webkit, firefox };

const YEAR = 2025;
const RATE = '9.101';
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September',
  'October', 'November', 'December'];
// Words the safe diagnostic file may keep (fbar_cih.py KEYWORDS == fbar-core.js KEYWORDS).
const KEYWORDS = new Set(['BANQUE', 'VILLE', 'N°', 'DE', 'COMPTE', 'CLE', 'DATES', 'OPER', 'VALEUR',
  'OPERATION-REFERENCE', 'DEBIT', 'CREDIT', 'SOLDE', 'DEPART', 'AU', 'AU :', ':', 'TOTAL', 'DES', 'MOUVEMENTS',
  'NOUVEAU', 'PAGE', 'REPORT', 'REPORTER', 'A', 'Sauf', 'erreur', 'RELEVE', 'AGENCE']);
// Plain-language check for messages shown to the user.
const JARGON = /exception|error:|undefined|null\b|NaN|stack|typeerror|\bat \w+ \(|pdf\.js|worker|\bjs\b|parse|regex|\[object/i;

// ------------------------------------------------------------------ helpers (independent of the app's code)

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const pdfsIn = (dir) => fs.readdirSync(dir).filter((f) => /\.pdf$/i.test(f)).sort().map((f) => path.join(dir, f));
const norm = (s) => String(s ?? '').replace(/[   ]/g, ' ').replace(/\s+/g, ' ').trim();
function usdCeil(cents, rate) { // ceil(cents / 100 / rate), exact
  const [i, f = ''] = rate.split('.');
  const num = BigInt(cents) * 10n ** BigInt(f.length);
  const den = BigInt(i + f) * 100n;
  return Number(num / den + (num % den ? 1n : 0n));
}
function fmtMad(cents) {
  const neg = cents < 0; const abs = Math.abs(cents);
  const units = String(Math.floor(abs / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
  return (neg ? '-' : '') + units + ',' + String(abs % 100).padStart(2, '0');
}
const usdText = (n) => '$' + String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
const niceDate = (iso) => MONTHS[+iso.slice(5, 7) - 1] + ' ' + (+iso.slice(8, 10)) + ', ' + iso.slice(0, 4);
const tail = (acct) => '...' + acct.slice(-6);
function parseCsv(text) {
  const rows = []; let row = []; let field = ''; let q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) {
      if (c === '"' && text[i + 1] === '"') { field += '"'; i++; } else if (c === '"') q = false; else field += c;
    } else if (c === '"') q = true;
    else if (c === ',') { row.push(field); field = ''; } else if (c === '\n') { row.push(field.replace(/\r$/, '')); rows.push(row); row = []; field = ''; } else field += c;
  }
  if (field !== '' || row.length) { row.push(field.replace(/\r$/, '')); rows.push(row); }
  return rows;
}
const centsOf = (s) => (s === '' || s == null ? null : Math.round(Number(s) * 100));

/** fbar_cih.py's printed summary -> { account: { maxCents, maxDate, usd, issues } } */
function parsePyOutput(text) {
  const accounts = {}; let cur = null;
  for (const line of text.split('\n')) {
    let m;
    if ((m = /^Account (.+?)\s+\(\d+ statements?\)/.exec(line))) { cur = m[1]; accounts[cur] = { issues: 0 }; }
    else if (cur && /^\s+! /.test(line)) accounts[cur].issues++;
    else if (cur && (m = /Maximum balance: (-?[\d ]+,\d{2}) MAD on (\d{4}-\d{2}-\d{2})/.exec(line))) {
      accounts[cur].maxCents = Number(m[1].replace(/ /g, '').replace(',', '')); accounts[cur].maxDate = m[2];
    } else if (cur && (m = /rounded up: \$([\d,]+)/.exec(line))) accounts[cur].usd = Number(m[1].replace(/,/g, ''));
  }
  return accounts;
}

// ------------------------------------------------------------------ result bookkeeping

const results = []; // { browser, scenario, status, checks, notes, error, seconds }
class Scenario {
  constructor(browser, name) { this.browser = browser; this.name = name; this.checks = []; this.notes = []; this.error = null; }
  ok(cond, msg, got) { this.checks.push({ level: cond ? 'ok' : 'fail', msg, got: cond ? undefined : got }); return !!cond; }
  warn(cond, msg, got) { this.checks.push({ level: cond ? 'ok' : 'warn', msg, got: cond ? undefined : got }); return !!cond; }
  note(s) { this.notes.push(s); }
  get status() {
    if (this.error || this.checks.some((c) => c.level === 'fail')) return 'FAIL';
    if (this.checks.some((c) => c.level === 'warn')) return 'WARN';
    return this.checks.length ? 'PASS' : 'SKIP';
  }
}

async function scenario(browserName, name, fn) {
  const sc = new Scenario(browserName, name);
  const t0 = Date.now();
  process.stdout.write(`[${browserName}] ${name} ... `);
  try { await fn(sc); } catch (err) { sc.error = String(err && err.stack || err).split('\n').slice(0, 4).join(' | '); }
  sc.seconds = (Date.now() - t0) / 1000;
  results.push(sc);
  console.log(sc.status + (sc.error ? '  (' + sc.error.slice(0, 300) + ')' : ''));
  for (const c of sc.checks.filter((x) => x.level !== 'ok')) {
    console.log(`    ${c.level.toUpperCase()} ${c.msg}${c.got !== undefined ? '  got: ' + JSON.stringify(c.got).slice(0, 500) : ''}`);
  }
  for (const n of sc.notes) console.log('    note: ' + n);
  return sc;
}

// ------------------------------------------------------------------ browser plumbing

const privacy = {}; // per browser: every URL seen, and the ones that are not file:/data:/blob:
function isLocal(url) { return /^(file|data|blob|about):/i.test(url); }

async function newContext(browser, browserName, options = {}) {
  const log = privacy[browserName];
  const context = await browser.newContext({
    acceptDownloads: true,
    viewport: options.viewport || { width: 1280, height: 900 },
    colorScheme: options.colorScheme || 'light',
    deviceScaleFactor: 1,
    ...(options.timezoneId ? { timezoneId: options.timezoneId } : {}),
    ...(options.locale ? { locale: options.locale } : {}),
  });
  context.__qa = { console: [], pageErrors: [], navigations: [] };
  await context.route('**/*', async (route) => {
    const url = route.request().url();
    log.routed.push(url);
    if (!isLocal(url)) { log.external.push({ via: 'route', url, during: log.current }); return route.abort(); }
    return route.continue();
  });
  context.on('request', (req) => {
    const url = req.url();
    log.requests.push(url);
    if (!isLocal(url)) log.external.push({ via: 'request', url, during: log.current });
  });
  context.on('page', (page) => {
    page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') context.__qa.console.push(m.type() + ': ' + m.text().slice(0, 300)); });
    page.on('pageerror', (e) => context.__qa.pageErrors.push(String(e && e.message || e).slice(0, 300)));
    page.on('websocket', (ws) => log.external.push({ via: 'websocket', url: ws.url(), during: log.current }));
    page.on('framenavigated', (f) => { if (f === page.mainFrame()) context.__qa.navigations.push(f.url()); });
  });
  await context.addInitScript(() => {
    window.__qaCsp = [];
    document.addEventListener('securitypolicyviolation', (e) => {
      window.__qaCsp.push({ directive: e.violatedDirective, blocked: e.blockedURI, line: e.lineNumber });
    });
  });
  return context;
}

async function openApp(context, url = PAGE_URL) {
  const page = await context.newPage();
  const t0 = Date.now();
  await page.goto(url, { waitUntil: 'load', timeout: 60000 });
  await page.waitForFunction(() => document.body && ['ready', 'done'].includes(document.body.dataset.state), null, { timeout: 60000 });
  page.__loadSeconds = (Date.now() - t0) / 1000;
  return page;
}

async function fileCount(page) { return page.evaluate(() => document.querySelectorAll('#file-list li').length); }

async function waitDone(page, expectedCount, timeout = 240000) {
  await page.waitForFunction((n) => {
    const lis = Array.from(document.querySelectorAll('#file-list li'));
    return document.body.dataset.state === 'done' && lis.length === n &&
      !lis.some((li) => li.dataset.status === 'waiting' || li.dataset.status === 'reading');
  }, expectedCount, { timeout, polling: 100 });
}

async function upload(page, files) {
  const before = await fileCount(page);
  const t0 = Date.now();
  await page.setInputFiles('#file-input', files);
  await waitDone(page, before + files.length);
  return (Date.now() - t0) / 1000;
}

/** Synthetic drag-and-drop of real File objects onto the drop zone (what a user does with Finder/Explorer). */
async function dropFiles(page, files, targetSelector = '#drop') {
  const payload = files.map((f) => ({ name: path.basename(f), b64: fs.readFileSync(f).toString('base64') }));
  const before = await fileCount(page);
  const t0 = Date.now();
  const prevented = await page.evaluate(({ payload, targetSelector }) => {
    const dt = new DataTransfer();
    for (const f of payload) {
      const bin = atob(f.b64); const bytes = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      dt.items.add(new File([bytes], f.name, { type: 'application/pdf' }));
    }
    const target = document.querySelector(targetSelector);
    const fire = (type) => {
      let ev;
      try { ev = new DragEvent(type, { bubbles: true, cancelable: true, dataTransfer: dt }); } catch (e) { ev = null; }
      if (!ev || !ev.dataTransfer) {
        ev = new Event(type, { bubbles: true, cancelable: true });
        Object.defineProperty(ev, 'dataTransfer', { value: dt });
      }
      target.dispatchEvent(ev);
      return ev.defaultPrevented;
    };
    return { dragenter: fire('dragenter'), dragover: fire('dragover'), drop: fire('drop') };
  }, { payload, targetSelector });
  await waitDone(page, before + files.length);
  return { prevented, seconds: (Date.now() - t0) / 1000 };
}

/** Everything the user can see about the results, normalised. */
async function readResults(page) {
  return page.evaluate(() => {
    const txt = (el) => (el ? (el.textContent || '').replace(/[   ]/g, ' ').replace(/\s+/g, ' ').trim() : null);
    const vis = (el) => { if (!el) return false; const r = el.getBoundingClientRect(); const cs = getComputedStyle(el); return r.width > 0 && r.height > 0 && cs.visibility !== 'hidden' && cs.display !== 'none'; };
    const results = document.getElementById('results');
    const overall = document.querySelector('[data-testid=overall]');
    const accounts = Array.from(document.querySelectorAll('article.account')).map((card) => {
      const dd = {};
      card.querySelectorAll('dl.peak dt').forEach((dt) => { dd[txt(dt)] = txt(dt.nextElementSibling); });
      const problems = card.querySelector('.problems');
      const fbar = card.querySelector('[data-testid=fbar-number]');
      return {
        account: card.dataset.account, problems: Number(card.dataset.problems), maxCents: card.dataset.maxCents,
        maxDate: card.dataset.maxDate, usd: card.dataset.usd,
        badge: txt(card.querySelector('.account-head .badge')),
        heading: txt(card.querySelector('.account-head h3')),
        facts: txt(card.querySelector('.facts')),
        problemTexts: Array.from(card.querySelectorAll('.problems > ul > li')).map((li) => txt(li.firstChild)),
        problemsVisible: vis(problems),
        problemsBeforeNumber: !!(problems && fbar && (problems.compareDocumentPosition(fbar) & Node.DOCUMENT_POSITION_FOLLOWING)),
        notFinal: !!card.querySelector('.fbar-number.not-final'),
        usdShown: txt(card.querySelector('[data-testid=usd]')),
        madShown: txt(card.querySelector('[data-testid=mad]')),
        how: txt(card.querySelector('.fbar-number .how')),
        maxMad: dd['Highest balance'], reachedOn: dd['Reached on'], after: dd['After this transaction'],
        foundIn: dd['Found in'], acctForForm: Object.keys(dd).filter((k) => /^Account number/i.test(k)).map((k) => dd[k])[0],
        months: Array.from(card.querySelectorAll('.month-table tbody tr')).map((tr) => tr.dataset.check),
        monthLabels: Array.from(card.querySelectorAll('.month-table tbody tr')).map((tr) => txt(tr.lastElementChild)),
      };
    });
    const files = Array.from(document.querySelectorAll('#file-list li')).map((li) => ({
      name: txt(li.querySelector('.name')), status: li.dataset.status, tone: li.dataset.tone, kind: li.dataset.kind,
      detail: txt(li.querySelector('.detail')),
      diag: !!Array.from(li.querySelectorAll('button')).find((b) => /diagnostic/i.test(b.textContent)),
    }));
    const summaryRows = Array.from(document.querySelectorAll('table.summary-table tbody tr')).map((tr) => Array.from(tr.cells).map(txt));
    return {
      year: document.getElementById('year').value, rate: document.getElementById('rate').value,
      rateStatus: txt(document.getElementById('rate-status')),
      overall: overall ? { cls: overall.className, role: overall.getAttribute('role'), problems: overall.dataset.problems, text: txt(overall), first: results.firstElementChild === overall, visible: vis(overall) } : null,
      unusable: Array.from(document.querySelectorAll('[data-testid=unusable] li')).map(txt),
      totalUsd: txt(document.querySelector('[data-testid=total-usd]')),
      threshold: txt(document.querySelector('[data-testid=threshold]')),
      summaryRows, accounts, files,
      downloadsVisible: !document.getElementById('downloads').hidden,
      fatal: !document.getElementById('fatal').hidden,
    };
  });
}

/** The part of the results that must not depend on how/when files were added. */
function fingerprint(res) {
  return JSON.stringify({
    overall: res.overall && { cls: res.overall.cls, problems: res.overall.problems, text: res.overall.text },
    totalUsd: res.totalUsd, threshold: res.threshold, unusable: res.unusable.slice().sort(),
    summaryRows: res.summaryRows.slice().sort((a, b) => String(a[0]).localeCompare(String(b[0]))),
    accounts: res.accounts.slice().sort((a, b) => a.account.localeCompare(b.account)).map((a) => ({
      account: a.account, problems: a.problems, maxCents: a.maxCents, maxDate: a.maxDate, usd: a.usd, badge: a.badge,
      facts: a.facts, problemTexts: a.problemTexts, months: a.months, maxMad: a.maxMad, reachedOn: a.reachedOn,
      after: a.after, usdShown: a.usdShown,
    })),
  });
}

function diffFingerprints(a, b) {
  const A = JSON.parse(a), B = JSON.parse(b), out = [];
  const walk = (x, y, p) => {
    if (JSON.stringify(x) === JSON.stringify(y)) return;
    if (x && y && typeof x === 'object' && typeof y === 'object') {
      for (const k of new Set([...Object.keys(x), ...Object.keys(y)])) walk(x[k], y[k], p + '.' + k);
    } else out.push(`${p}: ${JSON.stringify(x)} vs ${JSON.stringify(y)}`);
  };
  walk(A, B, '');
  return out.slice(0, 8);
}

function checkExpected(sc, res, expAccounts, { label = '' } = {}) {
  const want = Object.keys(expAccounts).sort();
  const got = res.accounts.map((a) => a.account).sort();
  sc.ok(JSON.stringify(want) === JSON.stringify(got), `${label}accounts shown = ${want.map(tail).join(', ')}`, got);
  let totalUsd = 0;
  for (const acct of want) {
    const e = expAccounts[acct];
    const a = res.accounts.find((x) => x.account === acct);
    if (!a) continue;
    const usd = usdCeil(e.maxCents, RATE);
    totalUsd += usd;
    const t = tail(acct);
    sc.ok(Number(a.maxCents) === e.maxCents && a.maxDate === e.maxDate, `${label}${t}: max ${fmtMad(e.maxCents)} on ${e.maxDate} (data)`, { cents: a.maxCents, date: a.maxDate });
    sc.ok(norm(a.maxMad) === fmtMad(e.maxCents) + ' MAD', `${label}${t}: "Highest balance" shows ${fmtMad(e.maxCents)} MAD`, a.maxMad);
    sc.ok(a.reachedOn === niceDate(e.maxDate), `${label}${t}: "Reached on" shows ${niceDate(e.maxDate)}`, a.reachedOn);
    sc.ok(Number(a.usd) === usd && (a.usdShown || '').startsWith(usdText(usd)), `${label}${t}: FBAR number ${usdText(usd)} = ceil(MAD / ${RATE})`, { usd: a.usd, shown: a.usdShown });
    const exactCents = (BigInt(e.maxCents) * 1000n) / BigInt(RATE.replace('.', '')); // US cents, cut
    const exact = usdText(Number(exactCents / 100n)) + '.' + String(exactCents % 100n).padStart(2, '0');
    sc.ok((a.how || '').includes(fmtMad(e.maxCents) + ' MAD') && (a.how || '').includes('= ' + exact), `${label}${t}: formula line shows ${fmtMad(e.maxCents)} MAD / ${RATE} = ${exact}`, a.how);
    const row = res.summaryRows.find((r) => r[0] && r[0].replace(/\D/g, '').startsWith(acct));
    sc.ok(row && row.includes(usdText(usd)), `${label}${t}: summary table shows ${usdText(usd)}`, row);
    sc.ok(a.acctForForm && a.acctForForm.replace(/\D/g, '') === acct, `${label}${t}: account number for the form`, a.acctForForm);
    const missing = a.months.map((m, i) => (m === 'missing' ? i + 1 : null)).filter(Boolean);
    sc.ok(JSON.stringify(missing) === JSON.stringify(e.missingMonths), `${label}${t}: missing months = [${e.missingMonths}]`, a.months);
    sc.ok(a.months.length === 12 && a.months.every((m, i) => e.missingMonths.includes(i + 1) || m === 'ok'), `${label}${t}: every other month "OK"`, a.months);
    if (e.missingMonths.length) {
      const m = MONTHS[e.missingMonths[0] - 1];
      sc.ok(a.problemTexts.some((p) => p.includes(`statement for ${m} ${YEAR} is missing`)), `${label}${t}: problem "${m} ${YEAR} is missing" listed`, a.problemTexts);
      sc.ok(a.problemsVisible && a.problemsBeforeNumber, `${label}${t}: problem box visible, above the FBAR number`, { visible: a.problemsVisible, before: a.problemsBeforeNumber });
      sc.ok(a.notFinal && /not final/.test(a.badge || ''), `${label}${t}: number marked "not final"`, { notFinal: a.notFinal, badge: a.badge });
    } else {
      sc.ok(a.problems === 0 && /ready to use/i.test(a.badge || ''), `${label}${t}: no problem, "ready to use"`, { problems: a.problems, badge: a.badge, texts: a.problemTexts });
    }
  }
  if (want.length > 1) sc.ok(res.totalUsd === usdText(totalUsd), `${label}total of all accounts ${usdText(totalUsd)}`, res.totalUsd);
  return totalUsd;
}

function checkDiagnostic(text, secrets) {
  const problems = [];
  const lines = text.split('\n');
  const expectHead = [
    /^Safe diagnostic file - FBAR maximum balance tool \(bank statements\)$/,
    /^File: statement-\d+\.pdf \(the real file name is not included\)(, bank: (CIH Bank|Attijariwafa Bank|BMCE Bank of Africa))?$/,
    /^This shows only the layout of one statement: every letter is replaced by x and every digit by 9\.$/,
    /^It contains no names, no account numbers and no amounts\.$/,
    /^Tool build: \d{4}-\d{2}-\d{2} [0-9a-f]{8}$/,
    /^Situation: [a-z ]+( \(\d+ statements in the file\))?(, \d+ without account number)?, \d+ pages?$/,
  ];
  const bodyStart = lines.findIndex((l) => /^--- page \d+ /.test(l));
  const head = lines.slice(0, bodyStart < 0 ? expectHead.length : bodyStart).filter((l) => l !== '');
  if (head.length !== expectHead.length) problems.push({ kind: 'header', line: 'header has ' + head.length + ' lines: ' + JSON.stringify(head).slice(0, 300) });
  head.forEach((l, i) => { if (!expectHead[i] || !expectHead[i].test(l)) problems.push({ kind: 'header', line: l }); });
  let words = 0;
  for (const line of lines.slice(bodyStart < 0 ? lines.length : bodyStart)) {
    if (line === '' || /^--- page \d+ \(\d+x\d+\) ---$/.test(line) || /^vline x=-?\d+\.\d$/.test(line)) continue;
    for (const w of line.split(' | ')) {
      const m = /^(-?\d+\.\d)-(-?\d+\.\d)@(-?\d+):([\s\S]*)$/u.exec(w);
      if (!m) { problems.push({ kind: 'unparsable', text: JSON.stringify(w).slice(0, 80) }); continue; }
      words++;
      const t = m[4];
      if (KEYWORDS.has(t)) continue;
      for (const ch of t) {
        if (ch === 'x' || ch === '9') continue;
        const cp = 'U+' + ch.codePointAt(0).toString(16).toUpperCase().padStart(4, '0');
        if (/\p{L}/u.test(ch)) problems.push({ kind: 'letter', ch, cp });
        else if (/\p{N}/u.test(ch)) problems.push({ kind: 'digit', ch, cp });
        else if (/\p{M}/u.test(ch)) problems.push({ kind: 'mark', cp });
        else if (/[\p{Cc}\p{Cf}\p{Co}\p{Cn}\p{Cs}]/u.test(ch)) problems.push({ kind: 'control/private-use', cp });
      }
    }
  }
  for (const s of secrets) if (text.includes(s)) problems.push({ kind: 'secret', text: s });
  // collapse duplicates for the report
  const seen = new Map();
  for (const p of problems) { const k = JSON.stringify(p); seen.set(k, (seen.get(k) || 0) + 1); }
  return { words, problems: Array.from(seen, ([k, n]) => ({ ...JSON.parse(k), n })) };
}

async function download(page, clickFn, dir) {
  const [dl] = await Promise.all([page.waitForEvent('download', { timeout: 20000 }), clickFn()]);
  fs.mkdirSync(dir, { recursive: true });
  const name = dl.suggestedFilename();
  const p = path.join(dir, name);
  await dl.saveAs(p);
  const failure = await dl.failure();
  return { name, path: p, url: dl.url(), failure, text: fs.readFileSync(p, 'utf8') };
}

async function layoutMetrics(page) {
  return page.evaluate(() => {
    const vw = document.documentElement.clientWidth;
    const describe = (el) => el.tagName.toLowerCase() + (el.id ? '#' + el.id : '') + (el.className && typeof el.className === 'string' ? '.' + el.className.trim().split(/\s+/).join('.') : '');
    const visible = (el) => { const cs = getComputedStyle(el); const r = el.getBoundingClientRect(); return cs.display !== 'none' && cs.visibility !== 'hidden' && r.width > 0 && r.height > 0; };
    const clippedByScroller = (el) => { for (let p = el.parentElement; p && p !== document.body; p = p.parentElement) { if (/(auto|scroll|hidden|clip)/.test(getComputedStyle(p).overflowX)) return true; } return false; };
    const offenders = [];
    for (const el of document.querySelectorAll('body *')) {
      if (!visible(el)) continue;
      const r = el.getBoundingClientRect();
      if ((r.right > vw + 1 || r.left < -1) && !clippedByScroller(el) && !el.classList.contains('visually-hidden')) offenders.push(describe(el) + ` [${Math.round(r.left)}..${Math.round(r.right)}]`);
    }
    const parse = (c) => { const m = c.match(/rgba?\(([^)]+)\)/); if (!m) return null; const p = m[1].split(/[ ,/]+/).filter(Boolean).map(Number); return { r: p[0], g: p[1], b: p[2], a: p.length > 3 ? p[3] : 1 }; };
    const lum = (c) => { const f = (v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }; return 0.2126 * f(c.r) + 0.7152 * f(c.g) + 0.0722 * f(c.b); };
    const bgOf = (el) => {
      const layers = [];
      for (let p = el; p; p = p.parentElement) { const c = parse(getComputedStyle(p).backgroundColor); if (c && c.a > 0) { layers.push(c); if (c.a >= 1) break; } }
      let base = { r: 255, g: 255, b: 255 };
      const rootBg = parse(getComputedStyle(document.documentElement).backgroundColor);
      if (rootBg && rootBg.a > 0) base = rootBg;
      for (let i = layers.length - 1; i >= 0; i--) { const c = layers[i]; base = { r: c.r * c.a + base.r * (1 - c.a), g: c.g * c.a + base.g * (1 - c.a), b: c.b * c.a + base.b * (1 - c.a) }; }
      return base;
    };
    const small = new Map(), lowContrast = new Map();
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    for (let n = walker.nextNode(); n; n = walker.nextNode()) {
      const t = n.textContent.trim();
      if (!t) continue;
      const el = n.parentElement;
      if (!el || !visible(el) || el.closest('.visually-hidden')) continue;
      const cs = getComputedStyle(el);
      const size = parseFloat(cs.fontSize);
      if (size < 12) small.set(describe(el) + ' ' + size + 'px', t.slice(0, 50));
      const fg = parse(cs.color); if (!fg) continue;
      const bg = bgOf(el);
      const L1 = lum(fg), L2 = lum(bg);
      const ratio = (Math.max(L1, L2) + 0.05) / (Math.min(L1, L2) + 0.05);
      const large = size >= 24 || (size >= 18.66 && Number(cs.fontWeight) >= 700);
      if (ratio < (large ? 3 : 4.5)) lowContrast.set(describe(el), `${ratio.toFixed(2)} "${t.slice(0, 40)}"`);
    }
    const banner = document.querySelector('[data-testid=overall]');
    const firstAccount = document.querySelector('article.account');
    return {
      vw, overflowX: document.documentElement.scrollWidth - vw, offenders: offenders.slice(0, 12),
      small: Array.from(small, ([k, v]) => k + ': ' + v).slice(0, 12),
      lowContrast: Array.from(lowContrast, ([k, v]) => k + ': ' + v).slice(0, 12),
      bannerTop: banner ? Math.round(banner.getBoundingClientRect().top + window.scrollY) : null,
      firstAccountTop: firstAccount ? Math.round(firstAccount.getBoundingClientRect().top + window.scrollY) : null,
      docHeight: document.documentElement.scrollHeight, innerHeight: window.innerHeight,
      bodyFont: getComputedStyle(document.body).fontSize,
    };
  });
}

// ------------------------------------------------------------------ the scenarios

async function runBrowser(name, exp, data) {
  privacy[name] = { requests: [], routed: [], external: [], current: '' };
  const log = privacy[name];
  const browser = await ENGINES[name].launch({ headless: true });
  const version = browser.version();
  const shotsDir = path.join(OUT, 'screenshots', name);
  const dlDir = path.join(OUT, 'downloads', name);
  fs.mkdirSync(shotsDir, { recursive: true });
  const fake = pdfsIn(data.fake);
  const bad = pdfsIn(data.bad);
  let baseline = null; // fingerprint of the one-batch result

  const run = (title, fn) => { log.current = title; return scenario(name, title, fn); };
  const finish = async (sc, context) => {
    const q = context.__qa;
    sc.ok(q.pageErrors.length === 0, 'no uncaught JavaScript error', q.pageErrors);
    const strayNav = q.navigations.filter((u) => u !== PAGE_URL && u !== 'about:blank' && !(context.__qaAllowedUrl && u === context.__qaAllowedUrl));
    sc.ok(strayNav.length === 0, 'page never navigated away (e.g. to a dropped PDF)', strayNav);
    if (q.console.length) sc.note('console: ' + Array.from(new Set(q.console)).slice(0, 5).join(' || '));
    await context.close();
  };

  // 1. load
  await run('load + defaults + CSP meta', async (sc) => {
    const context = await newContext(browser, name);
    const page = await openApp(context);
    sc.note(`browser ${version}; page ready in ${page.__loadSeconds.toFixed(1)} s`);
    const st = await page.evaluate(() => {
      const meta = document.querySelector('meta[http-equiv="Content-Security-Policy" i]');
      const firstScript = document.querySelector('script');
      return {
        csp: meta && meta.getAttribute('content'),
        metaBeforeScripts: !!(meta && firstScript && (meta.compareDocumentPosition(firstScript) & Node.DOCUMENT_POSITION_FOLLOWING)),
        metaInHead: !!(meta && meta.parentElement === document.head),
        state: document.body.dataset.state, fatal: !document.getElementById('fatal').hidden,
        year: document.getElementById('year').value, rate: document.getElementById('rate').value,
        rateStatus: document.getElementById('rate-status').textContent,
        title: document.title,
        externalLinks: Array.from(document.querySelectorAll('[href],[src],[action],[formaction],[poster]')).map((e) => e.getAttribute('href') || e.getAttribute('src') || e.getAttribute('action') || e.getAttribute('formaction') || e.getAttribute('poster')).filter((u) => /^(https?:|\/\/|ftp:|wss?:)/i.test(u)),
        storage: { local: localStorage.length, session: sessionStorage.length, cookie: document.cookie },
      };
    });
    sc.ok(!st.fatal, 'all parts loaded (no "did not load correctly" box)');
    sc.ok(st.year === String(YEAR), `year preselected ${YEAR}`, st.year);
    sc.ok(st.rate === RATE, `rate prefilled ${RATE}`, st.rate);
    sc.ok(!!st.csp, 'CSP meta tag present', st.csp);
    sc.ok(st.metaInHead && st.metaBeforeScripts, 'CSP meta is in <head>, before every script', st);
    const dirs = Object.fromEntries((st.csp || '').split(';').map((d) => d.trim().split(/\s+/)).filter((d) => d[0]).map((d) => [d[0].toLowerCase(), d.slice(1)]));
    sc.ok(JSON.stringify(dirs['connect-src']) === JSON.stringify(["'none'"]), "connect-src 'none'", dirs['connect-src']);
    sc.ok(JSON.stringify(dirs['default-src']) === JSON.stringify(["'none'"]), "default-src 'none'", dirs['default-src']);
    const sources = Object.values(dirs).flat();
    sc.ok(!sources.some((s) => /^(https?:|wss?:|\*|\/\/)|\.[a-z]{2,}$/i.test(s)), 'no host / scheme / wildcard source in any directive', sources);
    sc.ok(!sources.includes("'unsafe-eval'"), "no 'unsafe-eval'", st.csp);
    sc.ok(st.externalLinks.length === 0, 'no external href/src in the page', st.externalLinks);
    await finish(sc, context);
  });

  // 2. main flow: all fake statements in one batch (file chooser)
  let mainPage = null, mainContext = null, mainRes = null;
  await run('all fake statements: max/date/USD + missing September', async (sc) => {
    mainContext = await newContext(browser, name);
    mainPage = await openApp(mainContext);
    const secs = await upload(mainPage, fake);
    sc.note(`${fake.length} statements read in ${secs.toFixed(1)} s`);
    mainRes = await readResults(mainPage);
    baseline = fingerprint(mainRes);
    checkExpected(sc, mainRes, exp.fake.accounts);
    sc.ok(mainRes.files.length === fake.length && mainRes.files.every((f) => f.tone === 'ok'), `all ${fake.length} files read`, mainRes.files.filter((f) => f.tone !== 'ok'));
    const ov = mainRes.overall;
    sc.ok(ov && /\bbad\b/.test(ov.cls) && ov.role === 'alert' && /Do not use these numbers yet/.test(ov.text), 'overall red banner "Do not use these numbers yet"', ov);
    sc.ok(ov && ov.first && ov.visible, 'banner is the first thing in the results, visible', ov);
    sc.ok(/more than \$10,000/.test(mainRes.threshold || ''), 'says the total is over $10,000', mainRes.threshold);
    sc.ok(mainRes.downloadsVisible, 'download section shown');
    // rate with a comma gives the same dollars
    await mainPage.fill('#rate', '9,101');
    const r2 = await readResults(mainPage);
    sc.ok(r2.accounts.every((a) => Number(a.usd) === usdCeil(exp.fake.accounts[a.account].maxCents, RATE)), 'rate typed as "9,101" gives the same dollars', r2.accounts.map((a) => a.usd));
    await mainPage.fill('#rate', RATE);
    const r3 = await readResults(mainPage);
    sc.ok(fingerprint(r3) === baseline, 'back to 9.101: results identical', diffFingerprints(fingerprint(r3), baseline));
    const pageErr = mainContext.__qa.pageErrors;
    sc.ok(pageErr.length === 0, 'no uncaught JavaScript error', pageErr);
  });

  // 3. downloads from the main page
  await run('CSV downloads (vs fbar_cih.py)', async (sc) => {
    if (!mainPage) throw new Error('main scenario did not run');
    const ref = data.ref;
    for (const kind of ['statements', 'transactions']) {
      const d = await download(mainPage, () => mainPage.click('#dl-' + kind), dlDir);
      sc.ok(!d.failure, `${kind} CSV downloaded (${d.name})`, d.failure);
      sc.ok(d.name === `fbar-${kind}-${YEAR}.csv`, `${kind} file name`, d.name);
      sc.ok(isLocal(d.url), `${kind} download is a local blob/data URL`, d.url.slice(0, 40));
      const text = d.text.replace(/^﻿/, '');
      const js = parseCsv(text.trimEnd());
      const py = parseCsv(fs.readFileSync(path.join(ref, kind + '.csv'), 'utf8').trimEnd());
      sc.ok(JSON.stringify(js[0]) === JSON.stringify(py[0]), `${kind}: same columns as fbar_cih.py`, { js: js[0], py: py[0] });
      sc.ok(js.length === py.length, `${kind}: ${py.length - 1} rows like fbar_cih.py`, js.length - 1);
      const numeric = new Set(['opening', 'total_debit', 'total_credit', 'closing', 'debit', 'credit', 'balance_after']);
      const keyOf = (r, h) => kind === 'statements' ? r[h.indexOf('file')] : r[h.indexOf('file')] + '#' + r[h.indexOf('operation_date')] + '#' + r[h.indexOf('balance_after')];
      const pyMap = new Map(py.slice(1).map((r) => [keyOf(r, py[0]), r]));
      let diffs = [];
      for (const r of js.slice(1)) {
        const p = pyMap.get(keyOf(r, js[0]));
        if (!p) { diffs.push('no python row for ' + keyOf(r, js[0])); continue; }
        js[0].forEach((col, i) => {
          const a = r[i], b = p[py[0].indexOf(col)];
          if (col === 'status') { if ((a === 'OK') !== (b === 'OK')) diffs.push(`${col}: ${a} vs ${b}`); return; }
          if (numeric.has(col)) { if (centsOf(a) !== centsOf(b)) diffs.push(`${keyOf(r, js[0])} ${col}: ${a} vs ${b}`); return; }
          if (a !== b) diffs.push(`${keyOf(r, js[0])} ${col}: ${JSON.stringify(a)} vs ${JSON.stringify(b)}`);
        });
      }
      sc.ok(diffs.length === 0, `${kind}: every value equals fbar_cih.py's`, diffs.slice(0, 6));
      sc.ok(d.text.startsWith('﻿'), `${kind}: UTF-8 byte-order mark for Excel`);
    }
  });

  // 4. safe diagnostic files: leak test
  const diagScenario = (title, files) => run(title, async (sc) => {
    const context = await newContext(browser, name);
    const page = await openApp(context);
    await upload(page, files);
    const res = await readResults(page);
    for (const f of files) {
      const base = path.basename(f);
      const item = res.files.find((x) => x.name === base);
      if (!sc.ok(item && item.diag, `${base}: diagnostic button offered`, item)) continue;
      const d = await download(page, () => page.evaluate((n) => {
        const li = Array.from(document.querySelectorAll('#file-list li')).find((l) => l.querySelector('.name').textContent === n);
        Array.from(li.querySelectorAll('button')).find((b) => /diagnostic/i.test(b.textContent)).click();
      }, base), path.join(dlDir, 'diag-' + base.replace(/\.pdf$/, '')));
      sc.ok(!d.failure && /^fbar-diagnostic-\d+\.txt$/.test(d.name), `${base}: diagnostic file downloaded (${d.name})`, d.name);
      sc.ok(!d.text.includes(base.replace(/\.pdf$/, '')), `${base}: file name not in the diagnostic file`);
      const chk = checkDiagnostic(d.text, exp.leak.secrets);
      sc.ok(chk.words > 5, `${base}: diagnostic has the word layout (${chk.words} words)`, chk.words);
      const bad = chk.problems.filter((p) => p.kind !== 'header');
      sc.ok(bad.length === 0, `${base}: only x, 9, punctuation and kept keywords`, bad.slice(0, 12));
      sc.ok(chk.problems.every((p) => p.kind !== 'header'), `${base}: header is the fixed text only`, chk.problems.filter((p) => p.kind === 'header'));
      const ctl = (d.text.match(/[\u0000-\u0008\u000b-\u001f\u007f-\u009f]/g) || []).length;
      sc.ok(ctl === 0, `${base}: no raw control characters`, ctl + ' control characters');
      if (base === 'no_tounicode.pdf' && ctl) {
        // Show that the "masked" text still encodes the real digits: digit d was drawn as code d+1.
        const body = d.text.split('\n').filter((l) => /@-?\d+:/.test(l));
        const decoded = body.flatMap((l) => l.split(' | ')).map((w) => w.replace(/^[^:]*:/, ''))
          .filter((t) => /[\u0001-\u0008]/.test(t))
          .map((t) => Array.from(t).map((ch) => { const c = ch.charCodeAt(0); return c >= 1 && c <= 10 ? String(c - 1) : ch; }).join(''));
        sc.note('decoded from the "safe" file (code-1): ' + decoded.join(' ') + '  (real account 230780000000000000009987, amount 48 213,56; digits 8 and 9 were turned into TAB/LF and split the words)');
      }
    }
    if (files.some((f) => /leak_statement/.test(f))) {
      const inProblems = await page.evaluate(() => Array.from(document.querySelectorAll('article.account .problems button')).map((b) => b.textContent));
      sc.ok(inProblems.length >= 1, 'diagnostic button also offered next to the account problem', inProblems);
    }
    await finish(sc, context);
  });
  await diagScenario('diagnostic file: accents, Arabic, other scripts', [path.join(data.leak, 'leak_statement.pdf'), path.join(data.leak, 'not_bank.pdf')]);
  await diagScenario('diagnostic file: PDF font without ToUnicode', [path.join(data.leak, 'no_tounicode.pdf')]);

  // 5. bad files mixed with the good ones
  await run('duplicate / password / scan / non-bank files', async (sc) => {
    const context = await newContext(browser, name);
    const page = await openApp(context);
    await upload(page, fake.concat(bad));
    const res = await readResults(page);
    const item = (n) => res.files.find((f) => f.name === n) || {};
    const L = item('locked.pdf'), S = item('scan.pdf'), N = item('not_bank.pdf'), D1 = item('0123_2025-05 (1).pdf'), D2 = item('0123_2025-05 again.pdf');
    sc.ok(L.kind === 'password' && /password/i.test(L.detail) && /Save as PDF/i.test(L.detail), 'locked.pdf: says it is password-protected and how to fix', L);
    sc.ok(S.kind === 'scanned' && /scan/i.test(S.detail) && /online banking/.test(S.detail), 'scan.pdf: says it is a scan, use the downloaded PDF', S);
    sc.ok(N.kind === 'notcih' && /does not look like a bank statement this tool can read/.test(N.detail), 'not_bank.pdf: "does not look like a bank statement this tool can read"', N);
    sc.ok(D1.kind === 'duplicate' && /already added/.test(D1.detail), 'exact copy: "already added ... ignored"', D1);
    sc.ok(D2.kind === 'duplicate' && /same account and same period/.test(D2.detail), 're-downloaded copy: "same account and same period ... ignored"', D2);
    for (const it of [L, S, N, D1, D2]) sc.ok(it.detail && !JARGON.test(it.detail), `plain language for ${it.name}`, it.detail);
    sc.ok(res.unusable.length === 3 && res.unusable.every((t) => !JARGON.test(t)), 'results list the 3 unusable files (duplicates are not "failures")', res.unusable);
    sc.ok(/3 files could not be used/.test(res.overall && res.overall.text || ''), 'banner counts 3 unusable files', res.overall && res.overall.text);
    checkExpected(sc, res, exp.fake.accounts, { label: 'still correct: ' });
    const acc = res.accounts.find((a) => a.account.endsWith('0123'));
    sc.ok(acc && /^12 statements for 2025/.test(acc.facts), 'duplicates are not counted twice (12 statements for ...0123)', acc && acc.facts);
    // same file again, same name, in a later batch
    await upload(page, [path.join(data.fake, '0123_2025-01.pdf')]);
    const res2 = await readResults(page);
    const dups = res2.files.filter((f) => f.name === '0123_2025-01.pdf');
    sc.ok(dups.length === 2 && dups.some((f) => f.kind === 'duplicate'), 'same file added again later: flagged as already added', dups);
    sc.ok(JSON.stringify(res2.accounts.map((a) => [a.account, a.maxCents, a.maxDate, a.usd])) === JSON.stringify(res.accounts.map((a) => [a.account, a.maxCents, a.maxDate, a.usd])), 'results unchanged after the re-added file');
    // removing the bad files gives back the baseline
    await page.click('#clear-all');
    await upload(page, fake);
    const res3 = await readResults(page);
    sc.ok(fingerprint(res3) === baseline, '"Remove all files" then re-adding gives the baseline again', diffFingerprints(fingerprint(res3), baseline));
    await finish(sc, context);
  });

  // 6. two batches, and a second batch while the first is still being read
  await run('two batches = one batch', async (sc) => {
    const half = Math.ceil(fake.length / 2);
    // shuffle so that each batch mixes both accounts and months out of order
    const order = fake.slice().sort((a, b) => (path.basename(a).slice(-6) + a).localeCompare(path.basename(b).slice(-6) + b)).reverse();
    for (const mode of ['wait', 'busy']) {
      const context = await newContext(browser, name);
      const page = await openApp(context);
      if (mode === 'wait') {
        await upload(page, order.slice(0, half));
        const mid = await readResults(page);
        sc.ok(mid.overall && /Do not use these numbers yet/.test(mid.overall.text), 'after batch 1 (half the months): told not to use the numbers yet', mid.overall);
        await upload(page, order.slice(half));
      } else {
        await page.setInputFiles('#file-input', order.slice(0, half));
        await page.waitForFunction(() => document.body.dataset.state === 'busy', null, { timeout: 10000 }).catch(() => {});
        await page.setInputFiles('#file-input', order.slice(half));
        await waitDone(page, fake.length);
      }
      const res = await readResults(page);
      const fp = fingerprint(res);
      sc.ok(fp === baseline, `batches (${mode === 'wait' ? 'one after the other' : 'second added while first still reading'}) give the same result as one batch`, diffFingerprints(fp, baseline));
      const acctOrder = res.summaryRows.map((r) => (r[0] || '').replace(/\D/g, '').slice(-6));
      sc.warn(JSON.stringify(acctOrder) === JSON.stringify(mainRes.summaryRows.map((r) => (r[0] || '').replace(/\D/g, '').slice(-6))), `accounts listed in the same order as in one batch (${mode})`, acctOrder);
      await finish(sc, context);
    }
  });

  // 7. drag and drop (synthetic DataTransfer with real File objects)
  await run('drag and drop onto the page', async (sc) => {
    const context = await newContext(browser, name);
    const page = await openApp(context);
    const r = await dropFiles(page, fake, '#drop');
    sc.ok(r.prevented.drop && r.prevented.dragover, 'drop/dragover default prevented (browser will not open the PDF itself)', r.prevented);
    const res = await readResults(page);
    sc.ok(fingerprint(res) === baseline, `drop of ${fake.length} files: same result as the file chooser`, diffFingerprints(fingerprint(res), baseline));
    // a file dropped outside the drop zone (e.g. on the results) must also be taken, not open in the browser
    const r2 = await dropFiles(page, [path.join(data.extra, fs.readdirSync(data.extra)[0])], '#step-results');
    sc.ok(r2.prevented.drop, 'drop elsewhere on the page is caught too', r2.prevented);
    await finish(sc, context);
  });

  // 8. owner-password (permissions-only) encryption, the missing month supplied
  await run('owner-password PDF + September supplied', async (sc) => {
    const context = await newContext(browser, name);
    const page = await openApp(context);
    await upload(page, fake.concat(pdfsIn(data.extra)));
    const res = await readResults(page);
    const sep = res.files.find((f) => /owner-password/.test(f.name));
    sc.ok(sep && sep.tone === 'ok', 'statement encrypted with only an owner password is read normally', sep);
    const full = JSON.parse(JSON.stringify(exp.fake.accounts));
    for (const a of Object.values(full)) a.missingMonths = [];
    checkExpected(sc, res, full);
    sc.ok(res.overall && /\bok\b/.test(res.overall.cls) && /Everything checks out/.test(res.overall.text), 'banner: "Everything checks out"', res.overall);
    await finish(sc, context);
  });

  // 9. privacy: offline context + CSP enforcement probes
  await run('offline (context.setOffline(true))', async (sc) => {
    const context = await newContext(browser, name);
    await context.setOffline(true);
    const page = await openApp(context);
    const secs = await upload(page, fake.concat(bad));
    const res = await readResults(page);
    checkExpected(sc, res, exp.fake.accounts);
    sc.note(`offline run: ${fake.length + bad.length} files in ${secs.toFixed(1)} s`);
    const d = await download(page, () => page.click('#dl-statements'), path.join(dlDir, 'offline'));
    sc.ok(!d.failure && d.text.length > 100, 'CSV download works offline', d.failure);
    const perf = await page.evaluate(() => performance.getEntriesByType('resource').map((e) => e.name).filter((u) => !/^(data|blob|file):/.test(u)));
    sc.ok(perf.length === 0, 'performance timeline lists no remote resource', perf);
    const storage = await page.evaluate(async () => ({ local: localStorage.length, session: sessionStorage.length, cookie: document.cookie, idb: indexedDB.databases ? (await indexedDB.databases()).length : 'n/a' }));
    sc.ok(storage.local === 0 && storage.session === 0 && !storage.cookie && (storage.idb === 0 || storage.idb === 'n/a'), 'nothing stored in the browser (localStorage/session/cookies/IndexedDB)', storage);
    const csp = await page.evaluate(() => window.__qaCsp);
    sc.ok(csp.length === 0, 'the app itself triggered no CSP violation (it never tried to load anything)', csp);
    await finish(sc, context);
  });

  await run('CSP blocks network APIs (probe)', async (sc) => {
    const context = await newContext(browser, name);
    const page = await openApp(context);
    const before = log.external.length;
    // Runs as a real inline <script> of the page (allowed by script-src 'unsafe-inline'), so the page's CSP
    // applies exactly as it would to the app's own code (Playwright's evaluate() may bypass parts of CSP).
    const out = await page.evaluate(async () => {
      window.__probe = null;
      const s = document.createElement('script');
      s.textContent = `(async () => {
        const r = {}; const host = 'https://qa-csp-probe.invalid/';
        try { await fetch(host + 'fetch'); r.fetch = 'NOT blocked'; } catch (e) { r.fetch = 'blocked'; }
        try { const x = new XMLHttpRequest(); x.open('GET', host + 'xhr'); x.send(); r.xhr = 'sent'; } catch (e) { r.xhr = 'blocked'; }
        try { new Image().src = host + 'img.png'; } catch (e) {}
        try { r.beacon = navigator.sendBeacon(host + 'beacon', 'x') ? 'queued' : 'refused'; } catch (e) { r.beacon = 'blocked'; }
        try { new WebSocket('wss://qa-csp-probe.invalid/ws'); r.ws = 'created'; } catch (e) { r.ws = 'blocked'; }
        try { new EventSource(host + 'sse'); r.sse = 'created'; } catch (e) { r.sse = 'blocked'; }
        try { const s2 = document.createElement('script'); s2.src = host + 's.js'; document.head.appendChild(s2); } catch (e) {}
        try { const l = document.createElement('link'); l.rel = 'stylesheet'; l.href = host + 's.css'; document.head.appendChild(l); } catch (e) {}
        try { const f = document.createElement('iframe'); f.src = host + 'frame'; document.body.appendChild(f); } catch (e) {}
        try { const ff = document.createElement('style'); ff.textContent = '@font-face{font-family:q;src:url(' + host + 'f.woff)} body{font-family:q}'; document.head.appendChild(ff); } catch (e) {}
        try { eval('1'); r.eval = 'NOT blocked'; } catch (e) { r.eval = 'blocked'; }
        try { new Function('return 1')(); r.newFunction = 'NOT blocked'; } catch (e) { r.newFunction = 'blocked'; }
        window.__probe = r;
      })();`;
      // appended from a timer, i.e. after this evaluate() returns: Playwright's evaluate() window allows eval
      setTimeout(() => document.head.appendChild(s), 50);
      for (let i = 0; i < 100 && !window.__probe; i++) await new Promise((res) => setTimeout(res, 50));
      await new Promise((res) => setTimeout(res, 2500));
      return Object.assign({}, window.__probe, { violations: Array.from(new Set(window.__qaCsp.map((v) => v.directive.split(' ')[0]))) });
    });
    const seen = log.external.slice(before);
    // these probe requests never leave (aborted by the QA route handler, and .invalid never resolves)
    log.external.splice(before);
    const reachedNetwork = Array.from(new Set(seen.filter((e) => e.via === 'route').map((e) => e.url)));
    const announced = Array.from(new Set(seen.filter((e) => e.via !== 'route').map((e) => e.url)));
    sc.ok(reachedNetwork.length === 0, 'no probe request got past the CSP to the network layer', reachedNetwork);
    sc.ok(out.fetch === 'blocked', 'fetch() blocked', out);
    sc.ok(out.eval === 'blocked' && out.newFunction === 'blocked', 'eval() / new Function() blocked', out);
    sc.note('CSP violations reported: ' + out.violations.join(', ') + '; xhr: ' + out.xhr + '; sendBeacon: ' + out.beacon + '; WebSocket: ' + out.ws + '; EventSource: ' + out.sse);
    if (announced.length) sc.note('blocked by CSP but still announced as "request" events (not sent): ' + announced.map((u) => u.replace('https://qa-csp-probe.invalid/', '')).join(', '));
    await finish(sc, context);
  });

  await run('timezones (US, Asia, UTC+14) and fr/ar locales', async (sc) => {
    for (const [timezoneId, locale] of [['America/Los_Angeles', 'en-US'], ['America/New_York', 'fr-FR'], ['Pacific/Kiritimati', 'ar-MA'], ['Asia/Tokyo', 'en-GB']]) {
      const context = await newContext(browser, name, { timezoneId, locale });
      const page = await openApp(context);
      await upload(page, fake);
      const res = await readResults(page);
      const tz = await page.evaluate(() => Intl.DateTimeFormat().resolvedOptions().timeZone + ' ' + navigator.language);
      sc.ok(fingerprint(res) === baseline, `${timezoneId} / ${locale} (page sees ${tz}): same result`, diffFingerprints(fingerprint(res), baseline));
      sc.ok(res.year === String(YEAR) && res.rate === RATE, `${timezoneId} / ${locale}: year ${YEAR} and rate ${RATE} prefilled`, { year: res.year, rate: res.rate });
      await finish(sc, context);
    }
  });

  await run('interrupted download + JPEG photo', async (sc) => {
    const context = await newContext(browser, name);
    const page = await openApp(context);
    const files = fs.readdirSync(data.broken).sort().map((f) => path.join(data.broken, f));
    await upload(page, fake.concat(files));
    const res = await readResults(page);
    for (const f of files) {
      const it = res.files.find((x) => x.name === path.basename(f)) || {};
      sc.ok(it.tone && it.tone !== 'ok' && it.detail && !JARGON.test(it.detail), `${path.basename(f)}: flagged in plain language`, it);
    }
    const photo = res.files.find((x) => /\.jpg$/.test(x.name)) || {};
    sc.ok(photo.kind === 'notpdf', 'photo: "not a PDF file"', photo);
    const trunc = res.files.find((x) => /interrupted/.test(x.name)) || {};
    sc.note(`interrupted download -> kind=${trunc.kind || '-'} tone=${trunc.tone}: "${trunc.detail}"`);
    const acc = res.accounts.find((a) => a.account.endsWith('0245'));
    sc.ok(acc && acc.problems > 0 && /not final/.test(acc.badge || ''), 'account ...0245 still not final (September not really supplied)', acc && { problems: acc.problems, badge: acc.badge, texts: acc.problemTexts });
    sc.ok(res.overall && /Do not use these numbers yet/.test(res.overall.text), 'banner still says "Do not use these numbers yet"', res.overall && res.overall.text);
    await finish(sc, context);
  });

  await run('page saved in a folder with spaces/accents', async (sc) => {
    const dir = path.join(OUT, 'Téléchargements de Zoé', 'Mes documents');
    fs.mkdirSync(dir, { recursive: true });
    const copy = path.join(dir, 'FBAR-Max-Balance (1).html');
    fs.copyFileSync(HTML, copy);
    const url = pathToFileURL(copy).href;
    const context = await newContext(browser, name);
    context.__qaAllowedUrl = url;
    const page = await openApp(context, url);
    await upload(page, fake);
    const res = await readResults(page);
    sc.ok(fingerprint(res) === baseline, 'opened from ".../Téléchargements de Zoé/Mes documents/FBAR-Max-Balance (1).html": same result', diffFingerprints(fingerprint(res), baseline));
    await finish(sc, context);
  });

  await run('statements from 2024 and 2026 (huge balances) ignored', async (sc) => {
    const context = await newContext(browser, name);
    const page = await openApp(context);
    const others = pdfsIn(data.otherYears);
    await upload(page, fake.concat(others));
    const res = await readResults(page);
    checkExpected(sc, res, exp.fake.accounts);
    for (const f of others) {
      const it = res.files.find((x) => x.name === path.basename(f)) || {};
      sc.ok(/not part of 2025/.test(it.detail || ''), `${path.basename(f)}: "not part of 2025, so it is not used"`, it);
    }
    const a = res.accounts.find((x) => x.account.endsWith('0123'));
    sc.ok(a && /2 statements from another year \(not used\)/.test(a.facts || ''), 'account says "2 statements from another year (not used)"', a && a.facts);
    await finish(sc, context);
  });

  await run('edge statements vs fbar_cih.py', async (sc) => {
    const context = await newContext(browser, name);
    const page = await openApp(context);
    await upload(page, pdfsIn(data.edge));
    const res = await readResults(page);
    for (const [acct, py] of Object.entries(data.edgePy)) {
      if (!/^\d+$/.test(acct)) continue; // UNKNOWN ACCOUNT = the scan and the letter, rejected by the app
      const a = res.accounts.find((x) => x.account === acct);
      if (!sc.ok(!!a, `${tail(acct)} shown`, res.accounts.map((x) => x.account))) continue;
      sc.ok(Number(a.maxCents) === py.maxCents && a.maxDate === py.maxDate, `${tail(acct)}: max ${fmtMad(py.maxCents)} on ${py.maxDate}, like fbar_cih.py`, { app: [a.maxCents, a.maxDate], py });
      sc.ok(Number(a.usd) === py.usd, `${tail(acct)}: ${usdText(py.usd)} like fbar_cih.py`, a.usd);
      sc.ok((a.problems > 0) === (py.issues > 0) && (py.issues === 0 || /not final/.test(a.badge || '')), `${tail(acct)}: problems flagged (fbar_cih.py: ${py.issues})`, { problems: a.problems, badge: a.badge, texts: a.problemTexts });
      for (const t of a.problemTexts) sc.ok(!JARGON.test(t), `${tail(acct)}: plain language: "${t.slice(0, 70)}"`, t);
    }
    const unusable = res.files.filter((f) => f.tone === 'bad').map((f) => f.name).sort();
    sc.ok(JSON.stringify(unusable) === JSON.stringify(['letter.pdf', 'scanned.pdf']), 'scan and letter rejected', unusable);
    await finish(sc, context);
  });

  // 10. performance: 24 statements
  await run('performance: 24 statements', async (sc) => {
    const context = await newContext(browser, name);
    const page = await openApp(context);
    const files = pdfsIn(data.full24);
    const secs = await upload(page, files);
    const res = await readResults(page);
    checkExpected(sc, res, exp.full24.accounts);
    sc.ok(res.overall && /Everything checks out/.test(res.overall.text), 'banner: "Everything checks out"', res.overall);
    sc.perf = { files: files.length, seconds: secs, load: page.__loadSeconds };
    sc.ok(secs < 60, `${files.length} statements processed in ${secs.toFixed(1)} s (limit 60 s)`, secs);
    sc.note(`${files.length} statements: ${secs.toFixed(1)} s (${(secs / files.length).toFixed(2)} s/file); page load ${page.__loadSeconds.toFixed(1)} s`);
    await finish(sc, context);
  });

  if (mainContext) await mainContext.close();

  // 11. layout screenshots
  if (SHOTS) {
    await run('layout 1280/390 x light/dark', async (sc) => {
      for (const width of [1280, 390]) {
        for (const scheme of ['light', 'dark']) {
          const tag = `${width}-${scheme}`;
          const context = await newContext(browser, name, { viewport: { width, height: width === 390 ? 844 : 900 }, colorScheme: scheme });
          const page = await openApp(context);
          await page.screenshot({ path: path.join(shotsDir, `${tag}-1-empty.png`), fullPage: true });
          const m0 = await layoutMetrics(page);
          await upload(page, fake.concat(bad));
          await page.evaluate(() => window.scrollTo(0, 0));
          await page.screenshot({ path: path.join(shotsDir, `${tag}-2-viewport-after-upload.png`) });
          await page.screenshot({ path: path.join(shotsDir, `${tag}-3-results-full.png`), fullPage: true });
          const m = await layoutMetrics(page);
          // results area alone, for a closer look
          const results = await page.$('#step-results');
          if (results) await results.screenshot({ path: path.join(shotsDir, `${tag}-4-results-section.png`) });
          sc.ok(m0.overflowX <= 0 && m.overflowX <= 0, `${tag}: no horizontal page scroll`, { empty: m0.overflowX, results: m.overflowX });
          sc.warn(m.offenders.length === 0, `${tag}: nothing sticks out of the screen`, m.offenders);
          sc.warn(m.small.length === 0, `${tag}: no text smaller than 12px`, m.small);
          sc.warn(m.lowContrast.length === 0, `${tag}: text contrast >= WCAG AA`, m.lowContrast);
          sc.note(`${tag}: page ${m.docHeight}px tall; results banner at y=${m.bannerTop} (screen height ${m.innerHeight}); first account at y=${m.firstAccountTop}`);
          await finish(sc, context);
        }
      }
    });
  }

  await browser.close();
  return version;
}

// ------------------------------------------------------------------ main

async function main() {
  if (!fs.existsSync(HTML)) { console.error('Missing ' + HTML + ' (build it first: node build.mjs)'); process.exit(2); }
  fs.mkdirSync(OUT, { recursive: true });
  const dataDir = path.join(OUT, 'data');
  console.log('QA output: ' + OUT);
  console.log('Generating fake test files (qa/make_qa_files.py)...');
  execFileSync(PY, [path.join(QA, 'make_qa_files.py'), dataDir], { cwd: ROOT, stdio: ['ignore', 'ignore', 'inherit'] });
  const exp = JSON.parse(fs.readFileSync(path.join(dataDir, 'expected.json'), 'utf8'));
  const refDir = path.join(OUT, 'ref', 'fake');
  execFileSync(PY, [path.join(ROOT, 'fbar_cih.py'), path.join(dataDir, 'fake'), '--year', String(YEAR), '--rate', RATE, '--out', refDir], { cwd: ROOT, stdio: ['ignore', 'ignore', 'inherit'] });
  const edgeOut = execFileSync(PY, [path.join(ROOT, 'fbar_cih.py'), path.join(dataDir, 'edge'), '--year', String(YEAR), '--rate', RATE, '--out', path.join(OUT, 'ref', 'edge')], { cwd: ROOT, encoding: 'utf8' });
  const data = {
    edge: path.join(dataDir, 'edge'), edgePy: parsePyOutput(edgeOut), otherYears: path.join(dataDir, 'other_years'),
    fake: path.join(dataDir, 'fake'), full24: path.join(dataDir, 'full24'), bad: path.join(dataDir, 'bad'), broken: path.join(dataDir, 'broken'),
    extra: path.join(dataDir, 'extra'), leak: path.join(dataDir, 'leak'), ref: refDir,
  };
  const html = fs.readFileSync(HTML, 'utf8');
  const build = (html.match(/data-build="([^"]*)"/) || [])[1];
  const stat = fs.statSync(HTML);
  console.log(`Page: ${HTML}\n  build ${build}, ${(stat.size / 1024).toFixed(0)} KB, modified ${stat.mtime.toISOString()}`);
  console.log('Expected (from tests/make_fake_statements.py):\n  ' + exp.fake.generatorOutput.trim().split('\n').join('\n  '));

  const versions = {};
  for (const b of BROWSERS) {
    try { versions[b] = await runBrowser(b, exp, data); } catch (err) {
      console.log(`[${b}] could not run: ${err.message.split('\n')[0]}`);
      results.push(Object.assign(new Scenario(b, 'launch'), { error: err.message.split('\n')[0] }));
    }
  }

  // privacy verdict per browser
  for (const b of BROWSERS) {
    const p = privacy[b];
    if (!p) continue;
    const sc = new Scenario(b, 'privacy: every request is file:/data:/blob:');
    const ext = p.external;
    sc.ok(ext.length === 0, 'no request to anything other than file:, data:, blob:', ext.slice(0, 10));
    const schemes = Array.from(new Set(p.requests.concat(p.routed).map((u) => u.split(':')[0])));
    sc.note(`${p.requests.length} requests seen by page.on('request'), ${p.routed.length} by context.route; schemes: ${schemes.join(', ')}`);
    results.push(sc);
  }

  // table
  const names = Array.from(new Set(results.map((r) => r.name)));
  const pad = (s, n) => String(s).padEnd(n);
  console.log('\n' + pad('Scenario', 58) + BROWSERS.map((b) => pad(b, 10)).join(''));
  for (const n of names) {
    console.log(pad(n, 58) + BROWSERS.map((b) => pad((results.find((r) => r.browser === b && r.name === n) || { status: '-' }).status, 10)).join(''));
  }
  const perf = results.filter((r) => r.perf).map((r) => `${r.browser}: ${r.perf.seconds.toFixed(1)} s for ${r.perf.files} statements (page load ${r.perf.load.toFixed(1)} s)`);
  if (perf.length) console.log('\nPerformance: ' + perf.join('; '));
  console.log('Browsers: ' + Object.entries(versions).map(([b, v]) => `${b} ${v}`).join(', '));
  fs.writeFileSync(path.join(OUT, 'results.json'), JSON.stringify({ build, html: HTML, versions, results: results.map((r) => ({ browser: r.browser, scenario: r.name, status: r.status, seconds: r.seconds, error: r.error, notes: r.notes, checks: r.checks, perf: r.perf })) }, null, 2));
  console.log('Details: ' + path.join(OUT, 'results.json') + '\nScreenshots: ' + path.join(OUT, 'screenshots'));
  process.exit(results.some((r) => r.status === 'FAIL') ? 1 : 0);
}

main().catch((err) => { console.error(err); process.exit(2); });
